-- Argentina deep-dive ES/DE/FR translations (completing 317).
-- INSERT OR IGNORE throughout.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Clearance en tiempo real con CAE, universal desde 2019 -- uno de los mandatos de facturación electrónica más antiguos del mundo, todavía en evolución activa', 'Esta página de análisis refleja la orientación pública y las noticias disponibles a principios de agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las normas de facturación electrónica de Argentina cambian mediante resoluciones generales frecuentes de ARCA; confirme los requisitos vigentes directamente con ARCA o con un asesor fiscal local antes de basar en esta página sus decisiones de cumplimiento.', 'Argentina fue pionera en la facturación electrónica en la región, pasando de un sistema voluntario (2003) a uno obligatorio para los responsables inscriptos en IVA y los sujetos exentos bajo la RG 3749/2015, y luego a un mandato prácticamente universal que cubre a todos los monotributistas y las ventas a consumidor final desde el 1 de abril de 2019 (RG 4290/2018). En lugar de estabilizarse una vez universal, el sistema ha seguido recibiendo actualizaciones sustanciales: el cambio de nombre de AFIP a ARCA en 2024, una especificación técnica actualizada con IVA detallado y divulgación del tipo de cambio en 2025 (RG 5616/2024), un sistema de declaraciones de IVA prellenadas en noviembre de 2025 (RG 5705/2025, ''IVA Simple''), y una nueva ampliación de sectores más una opción de facturación mensual consolidada vigente desde el 1 de julio de 2026 (RG 5824/2026).', 'Argentina utiliza su propio esquema XML nacional en lugar de UBL o EN 16931 -- cada factura se autoriza en tiempo real y recibe un CAE (Código de Autorización Electrónico) antes de poder llegar al comprador, con un código QR obligatorio en toda copia impresa o en PDF desde 2021.', 'La cobertura es tan amplia como cualquiera que este sitio haya visto: B2B, B2G, B2C y exportaciones están todos dentro del alcance, para todo responsable inscripto en IVA, todo monotributista y, desde el 1 de julio de 2026, sectores adicionales que incluyen entidades financieras, aseguradoras, administradoras de tarjetas de crédito, medicina prepaga e instituciones educativas. Las entidades extranjeras registradas en Argentina enfrentan las mismas obligaciones que los contribuyentes locales.', 'Como el mandato ya es universal, la mayor parte del trabajo real para una empresa que ya opera en Argentina consiste en mantenerse al día con las frecuentes actualizaciones técnicas de ARCA -- más que en determinar si el mandato se aplica, cosa que casi con certeza ocurre.', 'Argentina respalda su mandato de facturación electrónica con un mecanismo de cumplimiento real: la clausura temporal del establecimiento por no emitir una factura conforme, y el rechazo del crédito de IVA del comprador si la factura que posee no tiene un CAE válido.', 'El régimen de facturación electrónica de Argentina comenzó como un sistema voluntario en 2003 y se volvió obligatorio para los responsables inscriptos en IVA y los sujetos exentos bajo la Resolución General 3749/2015. La Resolución General 4290/2018 completó la implementación: desde el 1 de abril de 2019, todos los monotributistas debieron emitir factura electrónica, incluidas las ventas a consumidores finales, volviendo el mandato prácticamente universal. El sistema funciona mediante clearance en tiempo real -- ARCA (renombrada de AFIP en 2024) valida el XML de cada factura y asigna un CAE antes de la entrega al comprador; una factura sin un CAE válido no tiene validez fiscal para ninguna de las partes. El mandato ha seguido evolucionando desde que se volvió universal: la RG 5616/2024 (vigente desde el 15 de abril de 2025) exigió web services actualizados y el detalle de IVA/tipo de cambio; la RG 5705/2025 introdujo declaraciones de IVA prellenadas construidas a partir de los datos de factura electrónica; y la RG 5824/2026 (vigente desde el 1 de julio de 2026) extendió el mandato a más sectores e introdujo una opción de facturación mensual consolidada para emisores de alto volumen. El incumplimiento conlleva una sanción real de clausura de dos a seis días bajo el artículo 40 de la Ley 11.683.', '🇦🇷' FROM countries WHERE name_en = 'Argentina';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Echtzeit-Clearing per CAE, seit 2019 universell -- eines der am längsten laufenden E-Rechnungsmandate der Welt, weiterhin aktiv in Entwicklung', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise und Berichterstattung mit Stand Anfang August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Argentiniens Vorschriften zur elektronischen Rechnungsstellung ändern sich durch häufige allgemeine Entschließungen der ARCA; bestätigen Sie die aktuellen Anforderungen direkt bei der ARCA oder einem örtlichen Steuerberater, bevor Sie sich für Compliance-Entscheidungen auf diese Seite verlassen.', 'Argentinien war Vorreiter der elektronischen Rechnungsstellung in der Region und wechselte von einem freiwilligen System (2003) zu einer Pflicht für umsatzsteuerlich registrierte und von der Umsatzsteuer befreite Steuerpflichtige nach RG 3749/2015, dann zu einer praktisch universellen Pflicht, die ab dem 1. April 2019 jeden Monotributista und jeden Verkauf an Endverbraucher abdeckt (RG 4290/2018). Statt sich nach Erreichen der Universalität zu stabilisieren, erhielt das System weiterhin substanzielle Aktualisierungen: eine Umbenennung von AFIP zu ARCA im Jahr 2024, eine aktualisierte technische Spezifikation mit aufgeschlüsselter USt. und Wechselkursangabe im Jahr 2025 (RG 5616/2024), ein System vorausgefüllter USt.-Erklärungen im November 2025 (RG 5705/2025, ''IVA Simple'') und eine weitere Sektorenausweitung samt monatlicher Sammelabrechnungsoption, die ab dem 1. Juli 2026 gilt (RG 5824/2026).', 'Argentinien verwendet ein eigenes inländisches XML-Schema statt UBL oder EN 16931 -- jede Rechnung wird in Echtzeit autorisiert und erhält einen CAE (Código de Autorización Electrónico), bevor sie den Käufer erreichen darf; seit 2021 ist auf jeder gedruckten oder als PDF vorliegenden Rechnung ein QR-Code vorgeschrieben.', 'Der Anwendungsbereich ist so breit, wie diese Seite es bislang gesehen hat: B2B, B2G, B2C und Exporte sind alle erfasst, für jeden umsatzsteuerlich registrierten Steuerpflichtigen, jeden Monotributista und, ab dem 1. Juli 2026, weitere Sektoren einschließlich Finanzinstitute, Versicherer, Kreditkartenverwalter, private Krankenversicherungen und Bildungseinrichtungen. Ausländische Unternehmen, die in Argentinien registriert sind, unterliegen denselben Pflichten wie inländische Steuerpflichtige.', 'Da die Pflicht bereits universell ist, besteht die eigentliche Arbeit für ein bereits in Argentinien tätiges Unternehmen größtenteils darin, mit ARCAs häufigen technischen Aktualisierungen Schritt zu halten -- statt zu klären, ob die Pflicht überhaupt gilt, was so gut wie sicher der Fall ist.', 'Argentinien untermauert seine E-Rechnungspflicht mit einem echten Durchsetzungsmechanismus: vorübergehende Schließung des Geschäftslokals bei Nichtausstellung einer konformen Rechnung, sowie Ablehnung des USt.-Vorsteuerabzugs des Käufers, wenn die ihm vorliegende Rechnung keinen gültigen CAE trägt.', 'Argentiniens E-Rechnungsregime begann 2003 als freiwilliges System und wurde nach der Allgemeinen Entschließung 3749/2015 für umsatzsteuerlich registrierte und von der Umsatzsteuer befreite Steuerpflichtige verpflichtend. Die Allgemeine Entschließung 4290/2018 vollendete die Umstellung: Ab dem 1. April 2019 musste jeder Monotributista elektronische Rechnungen ausstellen, einschließlich Verkäufen an Endverbraucher, wodurch die Pflicht praktisch universell wurde. Das System arbeitet mit Echtzeit-Clearing -- ARCA (2024 von AFIP umbenannt) validiert das XML jeder Rechnung und vergibt vor der Auslieferung an den Käufer einen CAE; eine Rechnung ohne gültigen CAE hat für keine der beiden Parteien steuerliche Gültigkeit. Die Pflicht entwickelte sich nach Erreichen der Universalität weiter: RG 5616/2024 (wirksam ab 15. April 2025) schrieb aktualisierte Web-Services sowie die Aufschlüsselung von USt. und Wechselkurs vor; RG 5705/2025 führte aus E-Rechnungsdaten erstellte, vorausgefüllte USt.-Erklärungen ein; und RG 5824/2026 (wirksam ab 1. Juli 2026) erweiterte die Pflicht auf weitere Sektoren und führte eine monatliche Sammelabrechnungsoption für Aussteller mit hohem Volumen ein. Bei Nichteinhaltung droht nach Artikel 40 des Gesetzes 11.683 eine echte Schließungsstrafe von zwei bis sechs Tagen.', '🇦🇷' FROM countries WHERE name_en = 'Argentina';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Clearance en temps réel par CAE, universelle depuis 2019 -- l''un des mandats de facturation électronique les plus anciens au monde, toujours en évolution active', 'Cette analyse par pays reflète les informations publiques et l''actualité disponibles début août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les règles de facturation électronique de l''Argentine évoluent au gré de résolutions générales fréquentes de l''ARCA ; confirmez les exigences actuelles directement auprès de l''ARCA ou d''un conseiller fiscal local avant de fonder toute décision de conformité sur cette page.', 'L''Argentine a fait figure de pionnière de la facturation électronique dans la région, passant d''un système volontaire (2003) à un système obligatoire pour les assujettis inscrits à la TVA et les sujets exonérés en vertu de la RG 3749/2015, puis à un mandat pratiquement universel couvrant chaque monotributista et chaque vente aux consommateurs finaux à partir du 1er avril 2019 (RG 4290/2018). Plutôt que de se stabiliser une fois devenu universel, le système a continué de recevoir des mises à jour substantielles : un changement de nom d''AFIP à ARCA en 2024, une spécification technique actualisée avec détail de la TVA et divulgation du taux de change en 2025 (RG 5616/2024), un système de déclarations de TVA pré-remplies en novembre 2025 (RG 5705/2025, « IVA Simple »), et une nouvelle extension sectorielle assortie d''une option de facturation mensuelle consolidée en vigueur depuis le 1er juillet 2026 (RG 5824/2026).', 'L''Argentine utilise son propre schéma XML national plutôt que l''UBL ou l''EN 16931 -- chaque facture est autorisée en temps réel et reçoit un CAE (Código de Autorización Electrónico) avant de pouvoir parvenir à l''acheteur, avec un code QR obligatoire sur toute copie imprimée ou en PDF depuis 2021.', 'La couverture est aussi large que tout ce que ce site a pu observer : le B2B, le B2G, le B2C et les exportations sont tous concernés, pour chaque assujetti inscrit à la TVA, chaque monotributista et, à partir du 1er juillet 2026, des secteurs supplémentaires incluant les établissements financiers, les assureurs, les gestionnaires de cartes de crédit, la santé prépayée et les établissements d''enseignement. Les entités étrangères enregistrées en Argentine sont soumises aux mêmes obligations que les contribuables nationaux.', 'Le mandat étant déjà universel, l''essentiel du travail réel pour une entreprise déjà présente en Argentine consiste à rester à jour face aux fréquentes mises à jour techniques de l''ARCA -- plutôt qu''à déterminer si le mandat s''applique, ce qui est presque certainement le cas.', 'L''Argentine assortit son obligation de facturation électronique d''un véritable mécanisme d''exécution : la fermeture temporaire de l''établissement en cas de défaut d''émission d''une facture conforme, et le rejet du crédit de TVA de l''acheteur si la facture qu''il détient ne comporte pas de CAE valide.', 'Le régime de facturation électronique de l''Argentine a débuté comme un système volontaire en 2003 et est devenu obligatoire pour les assujettis inscrits à la TVA et les sujets exonérés en vertu de la Résolution générale 3749/2015. La Résolution générale 4290/2018 a achevé la mise en œuvre : à partir du 1er avril 2019, chaque monotributista a dû émettre des factures électroniques, y compris pour les ventes aux consommateurs finaux, rendant le mandat pratiquement universel. Le système fonctionne par clearance en temps réel -- l''ARCA (renommée depuis l''AFIP en 2024) valide le XML de chaque facture et attribue un CAE avant la remise à l''acheteur ; une facture sans CAE valide n''a aucune validité fiscale pour aucune des deux parties. Le mandat a continué d''évoluer après être devenu universel : la RG 5616/2024 (en vigueur depuis le 15 avril 2025) a imposé des services web actualisés ainsi que le détail de la TVA et du taux de change ; la RG 5705/2025 a introduit des déclarations de TVA pré-remplies construites à partir des données de facturation électronique ; et la RG 5824/2026 (en vigueur depuis le 1er juillet 2026) a étendu le mandat à de nouveaux secteurs et introduit une option de facturation mensuelle consolidée pour les émetteurs à fort volume. Le non-respect entraîne une véritable sanction de fermeture de deux à six jours en vertu de l''article 40 de la loi 11.683.', '🇦🇷' FROM countries WHERE name_en = 'Argentina';

