INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato", "XML según el esquema propio de ARCA -- no UBL ni EN 16931"], ["Firma digital", "No se exige en la propia factura; el CAE es la validación en tiempo real de ARCA"], ["Código QR", "Obligatorio en toda factura impresa o en PDF desde 2021, con el CAE y los datos de la factura"], ["Tipos de factura", "A (comprador inscripto), B (consumidor final), C (monotributista), E (exportación), además de notas de crédito/débito"]]', 'Argentina construyó su propio formato mucho antes de que existiera la EN 16931, por lo que una factura nacional no se parece en nada a un documento UBL europeo -- los exportadores que tratan con compradores de la UE deben manejar ambos mundos por separado.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Format", "XML gemäß ARCAs eigenem inländischem Schema -- nicht UBL oder EN 16931"], ["Digitale Signatur", "Nicht auf der Rechnung selbst erforderlich; der CAE ist ARCAs eigene Echtzeitvalidierung"], ["QR-Code", "Seit 2021 auf jeder gedruckten oder als PDF vorliegenden Rechnung vorgeschrieben, mit CAE und Rechnungsdaten"], ["Rechnungstypen", "A (registrierter Käufer), B (Endverbraucher), C (Monotributista), E (Export), plus Gutschriften/Lastschriften"]]', 'Argentinien entwickelte sein eigenes Format lange bevor es EN 16931 überhaupt gab -- eine inländische Rechnung sieht daher völlig anders aus als ein europäisches UBL-Dokument; Exporteure mit EU-Käufern müssen beide Welten getrennt handhaben.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format", "XML selon le schéma propre d''ARCA -- ni UBL ni EN 16931"], ["Signature électronique", "Non exigée sur la facture elle-même ; le CAE constitue la validation en temps réel d''ARCA"], ["Code QR", "Obligatoire sur toute facture imprimée ou en PDF depuis 2021, comportant le CAE et les données de la facture"], ["Types de factures", "A (acheteur inscrit), B (consommateur final), C (monotributista), E (export), ainsi que notes de crédit/débit"]]', 'L''Argentine a conçu son propre format bien avant l''existence de l''EN 16931, si bien qu''une facture nationale ne ressemble en rien à un document UBL européen -- les exportateurs traitant avec des acheteurs de l''UE doivent gérer les deux univers séparément.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identificador fiscal", "CUIT (Clave Única de Identificación Tributaria)"], ["Registro", "Certificado digital fiscal ante ARCA, utilizado para solicitar la autorización de CAE"], ["Organismo regulador", "ARCA -- Agencia de Recaudación y Control Aduanero (renombrada de AFIP en 2024)"], ["Canales de emisión", "El portal web ''Comprobantes en Línea'', la aplicación móvil o una integración de web service certificada"]]', 'El cambio de nombre de AFIP a ARCA en 2024 fue organizativo, no técnico -- el CUIT, el proceso de CAE y los web services subyacentes se mantuvieron sin cambios.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerpflichtigen-ID", "CUIT (Clave Única de Identificación Tributaria)"], ["Registrierung", "Digitales Steuerzertifikat bei ARCA, verwendet zur Beantragung der CAE-Autorisierung"], ["Aufsichtsbehörde", "ARCA -- Agencia de Recaudación y Control Aduanero (2024 von AFIP umbenannt)"], ["Ausstellungskanäle", "Das Webportal ''Comprobantes en Línea'', die Mobil-App oder eine zertifizierte Web-Service-Integration"]]', 'Die Umbenennung von AFIP zu ARCA 2024 war organisatorisch, nicht technisch -- CUIT, CAE-Prozess und die zugrunde liegenden Web-Services blieben unverändert.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Identifiant fiscal", "CUIT (Clave Única de Identificación Tributaria)"], ["Enregistrement", "Certificat fiscal numérique auprès de l''ARCA, utilisé pour demander l''autorisation CAE"], ["Organisme de contrôle", "ARCA -- Agencia de Recaudación y Control Aduanero (renommée depuis l''AFIP en 2024)"], ["Canaux d''émission", "Le portail web ''Comprobantes en Línea'', l''application mobile, ou une intégration de service web certifiée"]]', 'Le changement de nom d''AFIP à ARCA en 2024 était organisationnel, non technique -- le CUIT, le processus de CAE et les services web sous-jacents sont restés inchangés.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Campos principales", "CUIT del emisor/comprador, tipo de factura, fecha, ítems, desglose de IVA"], ["Desde la RG 5616/2024", "IVA detallado por alícuota, y el tipo de cambio informado en facturas en moneda extranjera"], ["Conservación", "10 años, en el XML original, por parte de emisor y comprador -- se exige almacenamiento local por defecto"]]', 'El requisito de detalle de 2025 es una brecha real y vigente para las integraciones más antiguas que todavía informan un único total de IVA en lugar de un desglose por alícuota.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["Kernfelder", "CUIT von Aussteller/Käufer, Rechnungstyp, Datum, Positionen, USt.-Aufschlüsselung"], ["Seit RG 5616/2024", "USt. nach Steuersatz aufgeschlüsselt und der bei Fremdwährungsrechnungen verwendete Wechselkurs angegeben"], ["Aufbewahrung", "10 Jahre im Original-XML, sowohl bei Aussteller als auch Käufer -- standardmäßig inländische Speicherung vorgeschrieben"]]', 'Die Aufschlüsselungspflicht von 2025 ist eine reale, aktuelle Compliance-Lücke für ältere Integrationen, die noch einen einzigen USt.-Gesamtbetrag statt einer Aufschlüsselung nach Steuersatz melden.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Champs principaux", "CUIT de l''émetteur/de l''acheteur, type de facture, date, lignes, détail de la TVA"], ["Depuis la RG 5616/2024", "TVA détaillée par taux, et taux de change indiqué sur les factures en devise étrangère"], ["Conservation", "10 ans, au format XML d''origine, par l''émetteur et l''acheteur -- stockage national exigé par défaut"]]', 'L''exigence de détail de 2025 constitue une lacune réelle et actuelle pour les intégrations plus anciennes qui déclarent encore un total de TVA unique plutôt qu''une ventilation par taux.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo de facturación", "Clearance en tiempo real -- ARCA valida y emite un CAE antes de que la factura llegue al comprador"], ["Cobertura", "B2B, B2G, B2C y exportaciones -- prácticamente universal desde el 1 de abril de 2019"], ["Transmisión", "Web service certificado (H2H), el portal ''Comprobantes en Línea'' o la aplicación móvil"], ["Sin un CAE válido", "La factura no tiene validez fiscal ni para el emisor ni para el comprador"]]', 'Se trata de un verdadero modelo de clearance, no de reporte posterior -- la factura legalmente no existe como documento fiscal hasta que ARCA ya la aprobó.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["Rechnungsmodell", "Echtzeit-Clearing -- ARCA validiert und vergibt einen CAE, bevor die Rechnung den Käufer erreicht"], ["Abdeckung", "B2B, B2G, B2C und Exporte -- seit dem 1. April 2019 praktisch universell"], ["Übermittlung", "Zertifizierter Web-Service (H2H), das Portal ''Comprobantes en Línea'' oder die Mobil-App"], ["Ohne gültigen CAE", "Hat die Rechnung für weder Aussteller noch Käufer steuerliche Gültigkeit"]]', 'Dies ist ein echtes Clearing-Modell, kein nachträgliches Meldeverfahren -- die Rechnung existiert rechtlich erst als Steuerdokument, nachdem ARCA sie bereits genehmigt hat.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle de facturation", "Clearance en temps réel -- l''ARCA valide et délivre un CAE avant que la facture n''atteigne l''acheteur"], ["Couverture", "B2B, B2G, B2C et exportations -- pratiquement universelle depuis le 1er avril 2019"], ["Transmission", "Service web certifié (H2H), portail ''Comprobantes en Línea'', ou application mobile"], ["Sans CAE valide", "La facture n''a aucune validité fiscale, ni pour l''émetteur ni pour l''acheteur"]]', 'Il s''agit d''un véritable modèle de clearance, non d''un reporting a posteriori -- la facture n''existe légalement comme document fiscal qu''une fois déjà approuvée par l''ARCA.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Lo que realmente es obligatorio hoy', '[["Responsables inscriptos en IVA", "Obligatorio desde 2015 (RG 3749/2015)"], ["Monotributistas y ventas a consumidor final", "Obligatorio desde el 1 de abril de 2019 (RG 4290/2018)"], ["Sectores financiero, seguros, medicina prepaga y educación", "Nuevamente en alcance desde el 1 de julio de 2026 (RG 5824/2026)"], ["Entidades extranjeras registradas en Argentina", "Las mismas obligaciones que los contribuyentes locales"]]', 'Para 2019 ya no quedaba, en la práctica, ninguna categoría de contribuyente argentino emitiendo factura en papel -- la ampliación sectorial de 2026 agrega tipos de entidad específicos que las olas anteriores no habían nombrado explícitamente, más que abrir una brecha genuinamente nueva.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was heute tatsächlich verpflichtend ist', '[["Umsatzsteuerlich registrierte Steuerpflichtige", "Verpflichtend seit 2015 (RG 3749/2015)"], ["Monotributistas & Endverbraucherverkäufe", "Verpflichtend seit 1. April 2019 (RG 4290/2018)"], ["Finanz-, Versicherungs-, Krankenversicherungs- und Bildungssektor", "Neu erfasst ab 1. Juli 2026 (RG 5824/2026)"], ["In Argentinien registrierte ausländische Unternehmen", "Dieselben Pflichten wie inländische Steuerpflichtige"]]', 'Bis 2019 gab es in der Praxis keine verbleibende Kategorie argentinischer Steuerpflichtiger mehr, die Papierrechnungen ausstellte -- die Sektorenausweitung 2026 fügt lediglich bestimmte, zuvor nicht ausdrücklich genannte Unternehmenstypen hinzu, statt eine wirklich neue Lücke zu öffnen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui est réellement obligatoire aujourd''hui', '[["Assujettis inscrits à la TVA", "Obligatoire depuis 2015 (RG 3749/2015)"], ["Monotributistas et ventes aux consommateurs finaux", "Obligatoire depuis le 1er avril 2019 (RG 4290/2018)"], ["Secteurs financier, assurance, santé prépayée et éducation", "Nouvellement concernés depuis le 1er juillet 2026 (RG 5824/2026)"], ["Entités étrangères enregistrées en Argentine", "Les mêmes obligations que les contribuables nationaux"]]', 'Dès 2019, il ne restait, dans les faits, plus aucune catégorie de contribuable argentin émettant des factures papier -- l''extension sectorielle de 2026 ajoute des types d''entités spécifiques que les vagues précédentes n''avaient pas explicitement nommés, plutôt que d''ouvrir une lacune véritablement nouvelle.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'En evolución activa, no un sistema estático', '[["2024", "AFIP se renombra ARCA (Agencia de Recaudación y Control Aduanero)"], ["15 abr 2025", "Web services actualizados, IVA detallado y divulgación del tipo de cambio (RG 5616/2024)"], ["Nov 2025", "''IVA Simple'' -- declaraciones de IVA prellenadas a partir de los datos de factura electrónica (RG 5705/2025)"], ["1 jul 2026", "Se agregan nuevos sectores; se introduce la opción de facturación mensual consolidada (RG 5824/2026)"]]', 'Pocos mandatos tan maduros siguen recibiendo actualizaciones genuinas y con fecha a este ritmo -- conviene tratar a Argentina como un sistema para monitorear hacia adelante, no como un casillero que se marca una sola vez.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Aktiv in Entwicklung, kein stabiles System', '[["2024", "AFIP wird in ARCA umbenannt (Agencia de Recaudación y Control Aduanero)"], ["15. Apr 2025", "Aktualisierte Web-Services, aufgeschlüsselte USt. und Wechselkursangabe (RG 5616/2024)"], ["Nov 2025", "''IVA Simple'' -- aus E-Rechnungsdaten erstellte, vorausgefüllte USt.-Erklärungen (RG 5705/2025)"], ["1. Jul 2026", "Neue Sektoren hinzugefügt; monatliche Sammelabrechnungsoption eingeführt (RG 5824/2026)"]]', 'Nur wenige derart ausgereifte Mandate erhalten weiterhin in diesem Tempo echte, datierte Aktualisierungen -- Argentinien sollte als ein weiterhin zu beobachtendes System behandelt werden, nicht als einmal abgehakter Punkt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'En évolution active, pas un système figé', '[["2024", "L''AFIP est renommée ARCA (Agencia de Recaudación y Control Aduanero)"], ["15 avr. 2025", "Services web actualisés, TVA détaillée et divulgation du taux de change (RG 5616/2024)"], ["Nov. 2025", "« IVA Simple » -- déclarations de TVA pré-remplies à partir des données de facturation électronique (RG 5705/2025)"], ["1er juil. 2026", "Nouveaux secteurs ajoutés ; option de facturation mensuelle consolidée introduite (RG 5824/2026)"]]', 'Peu de mandats aussi mûrs continuent de recevoir de véritables mises à jour datées à ce rythme -- il convient de considérer l''Argentine comme un système à surveiller en continu, non comme une case cochée une fois pour toutes.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🔒 Una sanción de clausura real, no solo una multa', NULL, NULL, 'No emitir una factura conforme puede desencadenar la clausura temporal del establecimiento -- de dos a seis días bajo el artículo 40 de la Ley 11.683 -- que se duplica en severidad si se detecta una reincidencia dentro de los dos años. Es una consecuencia materialmente más dura que las multas monetarias fijas que usan la mayoría de los países que este sitio sigue.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🔒 Eine echte Schließungsstrafe, nicht nur eine Geldbuße', NULL, NULL, 'Die Nichtausstellung einer konformen Rechnung kann eine vorübergehende Schließung des Geschäftslokals auslösen -- zwei bis sechs Tage nach Artikel 40 des Gesetzes 11.683 -- die sich bei einem innerhalb von zwei Jahren festgestellten Wiederholungsfall verdoppelt. Das ist eine deutlich härtere Folge als die festen Geldbußen, die die meisten von dieser Seite erfassten Länder verwenden.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🔒 Une véritable sanction de fermeture, pas seulement une amende', NULL, NULL, 'Le défaut d''émission d''une facture conforme peut entraîner la fermeture temporaire de l''établissement -- de deux à six jours en vertu de l''article 40 de la loi 11.683 -- dont la sévérité double en cas de récidive constatée dans les deux ans. C''est une conséquence nettement plus sévère que les amendes forfaitaires utilisées par la plupart des pays suivis par ce site.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '💳 Sin CAE, no hay deducción', NULL, NULL, 'Una factura sin un CAE válido no tiene validez fiscal para ninguna de las dos partes de la operación: el emisor, en la práctica, no ha facturado en absoluto, y el comprador que la posee no puede reclamar el crédito de IVA ni la deducción del impuesto a las ganancias correspondiente. El paso de clearance no es una formalidad -- es lo que hace que el documento sea utilizable a efectos fiscales.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '💳 Kein CAE, kein Abzug', NULL, NULL, 'Eine Rechnung ohne gültigen CAE hat für keine der beiden Transaktionsseiten steuerliche Gültigkeit: Der Aussteller hat faktisch überhaupt nicht fakturiert, und der Käufer, der sie besitzt, kann den zugehörigen USt.-Vorsteuerabzug oder die Einkommensteuerabzug nicht geltend machen. Der Clearing-Schritt ist keine Formalität -- er ist das, was das Dokument überhaupt erst für steuerliche Zwecke nutzbar macht.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '💳 Pas de CAE, pas de déduction', NULL, NULL, 'Une facture sans CAE valide n''a aucune validité fiscale pour aucune des deux parties à la transaction : l''émetteur n''a, dans les faits, pas facturé du tout, et l''acheteur qui la détient ne peut réclamer le crédit de TVA ni la déduction d''impôt sur le revenu correspondants. L''étape de clearance n''est pas une formalité -- c''est elle qui rend le document utilisable à des fins fiscales.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🌎 Uno de los sistemas más antiguos de la región -- que sigue sin quedarse quieto', NULL, NULL, 'Argentina ha tenido alguna forma de factura electrónica desde 2003 y un mandato plenamente universal desde 2019, lo que la convierte en uno de los sistemas más maduros que sigue este sitio. En lugar de estabilizarse, ha recibido cambios sustanciales en casi todos los años desde entonces -- el cambio de nombre a ARCA en 2024, las actualizaciones técnicas y de reporte de 2025, y la ampliación sectorial de 2026 -- que merece la pena vigilar del mismo modo en que este sitio vigila a Turquía o Corea del Sur.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🌎 Eines der ältesten Systeme der Region -- immer noch nicht stillstehend', NULL, NULL, 'Argentinien betreibt seit 2003 irgendeine Form der elektronischen Rechnungsstellung und seit 2019 eine vollständig universelle Pflicht, was es zu einem der am weitesten entwickelten Systeme macht, die diese Seite erfasst. Statt sich zu stabilisieren, hat es seither in fast jedem Jahr substanzielle Änderungen erfahren -- die ARCA-Umbenennung 2024, die technischen und meldebezogenen Aktualisierungen 2025 und die Sektorenausweitung 2026 -- die es ebenso zu beobachten lohnt wie diese Seite die Türkei oder Südkorea beobachtet.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🌎 L''un des systèmes les plus anciens de la région -- toujours en mouvement', NULL, NULL, 'L''Argentine dispose d''une forme de facturation électronique depuis 2003 et d''un mandat pleinement universel depuis 2019, ce qui en fait l''un des systèmes les plus mûrs suivis par ce site. Plutôt que de se stabiliser, il a connu des changements substantiels presque chaque année depuis lors -- le changement de nom en ARCA en 2024, les mises à jour techniques et de déclaration de 2025, et l''extension sectorielle de 2026 -- qu''il convient de surveiller de la même façon que ce site surveille la Turquie ou la Corée du Sud.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Argentina' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'es', 'Factura no emitida, o emitida sin un CAE válido', 'Clausura del establecimiento de 2 a 6 días (Ley 11.683, art. 40)', 'Se duplica si se reitera dentro de 2 años' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Argentina' AND r.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'de', 'Rechnung nicht ausgestellt oder ohne gültigen CAE ausgestellt', '2-6 Tage Schließung des Geschäftslokals (Gesetz 11.683, Art. 40)', 'Verdoppelt sich bei Wiederholung innerhalb von 2 Jahren' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Argentina' AND r.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'fr', 'Facture non émise, ou émise sans CAE valide', 'Fermeture de l''établissement de 2 à 6 jours (loi 11.683, art. 40)', 'Double en cas de récidive dans les 2 ans' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Argentina' AND r.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'es', 'El comprador posee una factura sin un CAE válido', 'Se rechaza el crédito de IVA y la deducción del impuesto a las ganancias', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Argentina' AND r.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'de', 'Käufer besitzt eine Rechnung ohne gültigen CAE', 'USt.-Vorsteuerabzug und Einkommensteuerabzug werden abgelehnt', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Argentina' AND r.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT r.id, 'fr', 'L''acheteur détient une facture sans CAE valide', 'Le crédit de TVA et la déduction d''impôt sur le revenu sont rejetés', '—' FROM deep_dive_penalty_rows r JOIN countries c ON c.id = r.country_id WHERE c.name_en = 'Argentina' AND r.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Confirme que su sistema de facturación solicite y guarde un CAE para cada factura', 'Una factura sin un CAE válido no tiene validez fiscal -- es el control más importante para cualquier empresa que ya facture en Argentina.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Stellen Sie sicher, dass Ihr Rechnungssystem für jede Rechnung einen CAE anfordert und speichert', 'Eine Rechnung ohne gültigen CAE hat keine steuerliche Gültigkeit -- dies ist die wichtigste Prüfung für jedes Unternehmen, das bereits in Argentinien fakturiert.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Vérifiez que votre système de facturation demande et conserve un CAE pour chaque facture', 'Une facture sans CAE valide n''a aucune validité fiscale -- c''est le contrôle le plus important pour toute entreprise facturant déjà en Argentine.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Si es monotributista o vende a consumidores finales, confirme que la factura B electrónica esté plenamente implementada', 'Es obligatoria desde el 1 de abril de 2019, sin ninguna opción en papel restante para las categorías estándar.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Wenn Sie Monotributista sind oder an Endverbraucher verkaufen, stellen Sie sicher, dass die elektronische Rechnung Typ B vollständig eingeführt ist', 'Dies ist seit dem 1. April 2019 verpflichtend, ohne verbleibende Papieroption für Standardkategorien.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Si vous êtes monotributista ou vendez à des consommateurs finaux, vérifiez que la facturation électronique de type B est pleinement en place', 'Elle est obligatoire depuis le 1er avril 2019, sans option papier restante pour les catégories standard.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Actualícese a la especificación de web services de la RG 5616/2024 si aún no lo hizo', 'Las facturas deben detallar el IVA por alícuota e informar el tipo de cambio utilizado en las operaciones en moneda extranjera -- una brecha real para las integraciones que aún usan el esquema anterior.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Aktualisieren Sie auf die Web-Service-Spezifikation der RG 5616/2024, falls noch nicht geschehen', 'Rechnungen müssen die USt. nach Steuersatz aufschlüsseln und den bei Fremdwährungstransaktionen verwendeten Wechselkurs angeben -- eine echte Lücke für Integrationen, die noch das ältere Schema nutzen.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Passez à la spécification de services web de la RG 5616/2024 si vous ne l''avez pas encore fait', 'Les factures doivent détailler la TVA par taux et indiquer le taux de change utilisé pour les opérations en devise étrangère -- une lacune réelle pour les intégrations encore sur l''ancien schéma.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Si está en servicios financieros, seguros, medicina prepaga o educación, confirme su incorporación para la ampliación sectorial del 1 de julio de 2026', 'La RG 5824/2026 incorporó explícitamente a estos sectores, junto con un nuevo umbral de $10.000.000 para la identificación del consumidor.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Wenn Sie im Finanzdienstleistungs-, Versicherungs-, Krankenversicherungs- oder Bildungssektor tätig sind, bestätigen Sie die Umstellung für die Sektorenausweitung vom 1. Juli 2026', 'Die RG 5824/2026 hat diese Sektoren ausdrücklich einbezogen, zusammen mit einem neuen Schwellenwert von ARS 10.000.000 für die Verbraucheridentifizierung.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Si vous exercez dans les services financiers, l''assurance, la santé prépayée ou l''éducation, confirmez votre intégration pour l''extension sectorielle du 1er juillet 2026', 'La RG 5824/2026 a explicitement inclus ces secteurs, avec un nouveau seuil de 10 000 000 ARS pour l''identification du consommateur.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'es', 'Evalúe el comprobante de liquidación electrónica mensual para la facturación de clientes de alto volumen', 'La ''liquidación electrónica mensual'' introducida por la RG 5824/2026 permite a los emisores que califican consolidar las operaciones de un cliente en una sola factura mensual en lugar de una por operación.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'de', 'Prüfen Sie die monatliche Sammelabrechnung für die Rechnungsstellung volumenstarker Kunden', 'Die durch die RG 5824/2026 eingeführte ''liquidación electrónica mensual'' erlaubt es qualifizierten Ausstellern, die Transaktionen eines Kunden in einer einzigen monatlichen Rechnung statt einzeln zu konsolidieren.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT s.id, 'fr', 'Évaluez le bon de liquidation mensuelle consolidée pour la facturation des clients à fort volume', 'La ''liquidación electrónica mensual'' introduite par la RG 5824/2026 permet aux émetteurs éligibles de regrouper les opérations d''un client en une seule facture mensuelle plutôt qu''une par opération.' FROM deep_dive_steps s JOIN countries c ON c.id = s.country_id WHERE c.name_en = 'Argentina' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'es', 'ARCA -- Factura electrónica (emisión y autorización)' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Argentina' AND p.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'ARCA -- Elektronische Rechnung (Ausstellung und Autorisierung)' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Argentina' AND p.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'ARCA -- Facture électronique (émission et autorisation)' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Argentina' AND p.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'es', 'ARCA -- portal oficial' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Argentina' AND p.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'de', 'ARCA -- offizielles Portal' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Argentina' AND p.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT p.id, 'fr', 'ARCA -- portail officiel' FROM deep_dive_portals p JOIN countries c ON c.id = p.country_id WHERE c.name_en = 'Argentina' AND p.sort_order = 1;
